import random

import pytest


def make_ids(n: int, seed: int) -> list[int]:
    """Return n distinct record ids, deterministic for a given seed.

    The same (n, seed) always yields the same list in the same order.
    Uses no global RNG state and performs no I/O.

    Raises ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    rng = random.Random(seed)
    return rng.sample(range(1, 2**31), n)


def test_make_ids_length() -> None:
    assert len(make_ids(5, 42)) == 5


def test_make_ids_empty() -> None:
    assert make_ids(0, 42) == []


def test_make_ids_distinct() -> None:
    ids = make_ids(100, 7)
    assert len(set(ids)) == 100


def test_make_ids_deterministic() -> None:
    assert make_ids(20, 123) == make_ids(20, 123)


def test_make_ids_seed_changes_output() -> None:
    assert make_ids(20, 1) != make_ids(20, 2)


def test_make_ids_all_ints() -> None:
    assert all(isinstance(i, int) for i in make_ids(10, 99))


def test_make_ids_negative_n_raises() -> None:
    with pytest.raises(ValueError):
        make_ids(-1, 0)
